   <a class="skip-link" href="#maincontent">Skip to main content</a>

   <main id="maincontent" tabindex="-1">
     <section class="panel" aria-labelledby="page-title">
       <h1 id="page-title">Notification preferences</h1>
       <p class="intro">Choose the one way you would like us to contact you for updates and alerts.</p>

       <form id="preferences-form" novalidate>
         <div class="form-field">
           <fieldset aria-describedby="notification-help notification-error">
             <legend>How do you prefer to receive notifications? <span class="required" aria-hidden="true">*</span></legend>
             <p class="help-text" id="notification-help">* Required field. Select one option before submitting the form.</p>

             <div class="choices">
               <label class="choice" for="notify-email">
                 <input id="notify-email" type="radio" name="notificationPreference" value="Email" required>
                 <span class="choice-label">Email</span>
               </label>

               <label class="choice" for="notify-sms">
                 <input id="notify-sms" type="radio" name="notificationPreference" value="SMS" required>
                 <span class="choice-label">SMS</span>
               </label>

               <label class="choice" for="notify-push">
                 <input id="notify-push" type="radio" name="notificationPreference" value="Push Notifications" required>
                 <span class="choice-label">Push Notifications</span>
               </label>
             </div>
           </fieldset>

           <p class="error-text" id="notification-error" hidden>Error: Select how you prefer to receive notifications.</p>
         </div>

         <button type="submit">Save preference</button>
         <p class="status" id="form-status" aria-live="polite"></p>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById('preferences-form');
     const radios = Array.from(form.elements.notificationPreference);
     const errorMessage = document.getElementById('notification-error');
     const statusMessage = document.getElementById('form-status');

     function getSelectedRadio() {
       return radios.find((radio) => radio.checked);
     }

     function showError() {
       errorMessage.hidden = false;
       statusMessage.textContent = '';
       radios.forEach((radio) => radio.setAttribute('aria-invalid', 'true'));
     }

     function clearError() {
       errorMessage.hidden = true;
       radios.forEach((radio) => radio.removeAttribute('aria-invalid'));
     }

     radios.forEach((radio) => {
       radio.addEventListener('change', () => {
         clearError();
         statusMessage.textContent = '';
       });
     });

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       const selectedRadio = getSelectedRadio();

       if (!selectedRadio) {
         showError();
         radios[0].focus();
         return;
       }

       clearError();
       statusMessage.textContent = `Preference saved: ${selectedRadio.value}.`;
     });
   </script>
